```python
def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    result = []

    for original in s:
        if original == ' ':
            result.append(' ')
        else:
            result.append(sorted_words.pop(0))

    return ''.join(result)
